(function() {
    // 生成 UUID
    function generateUUID() {
        return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
            var r = Math.random() * 16 | 0,
                v = c == 'x' ? r : (r & 0x3 | 0x8);
            return v.toString(16);
        });
    }

    // Cookie 操作
    function getCookie(name) {
        var nameEQ = name + "=";
        var ca = document.cookie.split(';');
        for(var i = 0; i < ca.length; i++) {
            var c = ca[i];
            while (c.charAt(0) == ' ') c = c.substring(1, c.length);
            if (c.indexOf(nameEQ) == 0) return c.substring(nameEQ.length, c.length);
        }
        return null;
    }

    function setCookie(name, value, days) {
        var expires = "";
        if (days) {
            var date = new Date();
            date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
            expires = "; expires=" + date.toUTCString();
        }
        document.cookie = name + "=" + (value || "") + expires + "; path=/";
    }

    // 获取域名
    function getDomain() {
        return window.location.hostname;
    }

    // 获取当前页面路径
    function getPath() {
        return window.location.pathname;
    }

    // 获取或创建用户 UUID
    function getUserUUID() {
        var uuid = getCookie('suanzi_uuid');
        if (!uuid) {
            uuid = generateUUID();
            setCookie('suanzi_uuid', uuid, 365); // 有效期 1 年
        }
        return uuid;
    }

    // 调用 API 计数
    function count(type, path) {
        var domain = getDomain();
        var uuid = getUserUUID();
        
        var data = {
            domain: domain,
            type: type,
            path: path || '',
            uuid: uuid
        };

        // 发送计数请求
        fetch('/api/count', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(data)
        }).catch(function(error) {
            console.log('计数请求失败:', error);
        });

        // 查询并回填计数值
        var queryUrl = '/api/count?domain=' + encodeURIComponent(domain) + '&type=' + encodeURIComponent(type) + (path ? '&path=' + encodeURIComponent(path) : '');
        fetch(queryUrl)
            .then(function(response) {
                return response.json();
            })
            .then(function(data) {
                // 回填到对应的 span 标签
                var elementId = 'suanzi_value_' + type;
                var element = document.getElementById(elementId);
                if (element) {
                    element.textContent = data.count.toLocaleString();
                }
            })
            .catch(function(error) {
                console.log('查询计数失败:', error);
            });
    }

    // 页面加载完成后执行
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function() {
            // 站点 PV 计数
            count('site_pv');
            
            // 站点 UV 计数
            count('site_uv');
            
            // 页面 PV 计数
            count('page_pv', getPath());
        });
    } else {
        // DOM 已经加载完成
        count('site_pv');
        count('site_uv');
        count('page_pv', getPath());
    }
})();